/**
 * CV types — shape of the data in src/data/cv-raw-data.json
 *
 * Beginners: you usually do NOT edit this file.
 * Edit cv-raw-data.json instead. These types just describe what the JSON looks like.
 */

export interface Person {
	firstName: string;
	lastName: string;
	jobTitle: string;
	quote: string;
	email: string;
	phone: string;
	address: string;
}

export interface Photo {
	src: string;
	alt: string;
}

/** Options passed to fireConfetti() — same knobs as js-confetti */
export interface ConfettiOptions {
	emojis?: string[];
	emojiSize?: number;
	confettiColors?: string[];
	confettiRadius?: number;
	confettiNumber?: number;
}

export interface NavLink {
	label: string;
	href: string;
	/** Confetti config on click. Omit for no confetti. */
	confetti?: ConfettiOptions;
}

export interface ExperienceItem {
	role: string;
	company: string;
	start: string;
	end: string;
	description: string;
}

export interface EducationItem {
	degree: string;
	school: string;
	start: string;
	end: string;
	description: string;
}

export interface CvDownloadData {
	heading: string;
	buttonLabel: string;
	file: string;
}

/* Props each component receives (from index.astro) */

export interface NavbarProps {
	links: NavLink[];
}

export interface PillProps {
	link: NavLink;
}

export interface ProfileProps {
	person: Person;
	photo: Photo;
}

export interface ProfileContactProps {
	email: string;
	phone: string;
	address: string;
}

export interface ProfileQuoteProps {
	quote: string;
}

export interface CardProps {
	/** Optional border color (defaults to the avatar border / --card-border) */
	borderColor?: string;
	/** Stretch the card to full content width */
	fullWidth?: boolean;
}

export interface ExperienceProps {
	items: ExperienceItem[];
}

export interface EducationProps {
	items: EducationItem[];
}

export interface SkillsProps {
	items: string[];
}

export interface SoftSkillsProps {
	items: string[];
}

export interface LanguageItem {
	name: string;
	level: string;
}

export interface LanguagesProps {
	items: LanguageItem[];
}

export interface GeneralInfoItem {
	label: string;
	value: string;
}

export interface GeneralInformationProps {
	items: GeneralInfoItem[];
}

export interface CvDownloadProps {
	heading: string;
	buttonLabel: string;
	file: string;
}

export interface DownloadButtonProps {
	buttonLabel: string;
	file: string;
}

export interface FooterData {
	backToTop: NavLink;
}

export interface FooterProps {
	backToTop: NavLink;
}
